def build_agent(sandbox):
    # Base structure
    base = sandbox.add_beam(x=4.0, y=1.15, width=4.0, height=0.2, density=10.0)
    sandbox.weld_to_ground(base, (4.0, 1.15))

    # Platform connected via slider joint
    platform = sandbox.add_beam(x=4.0, y=1.5, width=4.0, height=0.2, density=5.0)
    joint = sandbox.add_joint(base, platform, (4.0, 1.5), type='slider', axis=(0, 1), lower_translation=-10.0, upper_translation=10.0)
    return {"body": base, "platform": platform, "joint": joint}

def agent_action(sandbox, agent_body, step_count):
    plat = agent_body.get("platform")
    if not plat:
        return
    joint = agent_body.get("joint")
    if not joint:
        return

    # Target height for the platform (object center at 9.0m)
    target_y = 9.0
    current_y = plat.position.y
    current_vel = plat.linearVelocity.y

    # Check if the platform is above the target and has been there for at least 3 seconds
    if current_y >= target_y:
        # Check if it's the first time the platform is above the target
        if 'sustain_timer' not in agent_body:
            agent_body['sustain_timer'] = step_count
        else:
            # Check if the time since reaching target is >= 3 seconds
            if step_count - agent_body['sustain_timer'] >= 3:
                # Sustain condition met, do nothing
                sandbox.set_slider_motor(joint, motor_speed=0.0, max_force=5000.0)
            else:
                # Maintain the platform with a small velocity
                # Ensure the velocity is not too low
                if current_vel < -0.4:
                    # Apply a small motor speed to counteract the velocity
                    sandbox.set_slider_motor(joint, motor_speed=0.5, max_force=5000.0)
                else:
                    # Keep the motor speed low to maintain position
                    sandbox.set_slider_motor(joint, motor_speed=0.0, max_force=5000.0)
    else:
        # Lift the platform
        sandbox.set_slider_motor(joint, motor_speed=5.0, max_force=5000.0)
